& \mathrm{Al}_2 \mathrm{O}_3+6 \mathrm{HCl} \longrightarrow 2 \mathrm{AlCl}_3+3 \mathrm{H}_2 \mathrm{O} \\
& \mathrm{Al}_2 \mathrm{O}_3+2 \mathrm{NaOH} \longrightarrow 2 \mathrm{NaAlO}_2+\mathrm{H}_2 \mathrm{O}
\end{aligned}

